{ arg out=0, freq=440, amp=0.1, gate=1, rq=0.5, cutoff=2000;
    var sig, env, lfo;
    env = EnvGen.ar(
        Env.adsr(0.5, 1.0, 0.7, 2.0, curve: -4),
        gate: gate,
        doneAction: 2
    );
    lfo = SinOsc.kr(0.1).range(0.8, 1.2); // Slow, subtle amplitude modulation
    sig = Saw.ar(freq) * amp * env * lfo;
    sig = LPF.ar(sig, cutoff * env.linlin(0, 1, 0.5, 1.5)); // Filter with cutoff modulated by envelope
    Out.ar(out, sig ! 2);
}
